/**
 * Generates the protocol's shared wire tables from one checked-in schema.
 *
 *   bun scripts/protocol/schema.ts           write both generated files
 *   bun scripts/protocol/schema.ts --check   fail while either is stale
 *
 * `packages/protocol/schema/wire.json` names every constant, limit, enum,
 * style field, element and operation member, command and event member, the
 * members of the nested payload objects inside them, and the menu shortcut
 * key names. The TypeScript output is plain data with no imports; the parsers
 * interpret it. The Rust output declares the constants, enums, `Style`,
 * `Limits`, the error texts built from constants, and the member tables the
 * hand-written element and operation decoders dispatch on; its command, event
 * and payload tables are test-only and check the derived serde types
 * (`native/protocol/src/schema_tests.rs`).
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'

export const SCHEMA_PATH = 'packages/protocol/schema/wire.json'
export const TYPESCRIPT_PATH = 'packages/protocol/src/wire-schema.ts'
export const RUST_PATH = 'native/protocol/src/wire/schema.rs'

type RustType = 'usize' | 'u16' | 'u32' | 'u64' | 'f64'

interface Constant {
  name: string
  value: number
  rust?: RustType
  doc?: string
  /** False when TypeScript reads the constant only through generated tables. */
  export?: boolean
}

type EnumValue = string | { name: string; doc?: string; required?: boolean }

interface EnumSpec {
  values: EnumValue[]
  doc?: string
  /** The exported TypeScript constant listing the values. */
  ts?: string
  default?: string
}

type StyleField = { name: string; doc?: string; decoration?: boolean } & (
  | { type: 'number' | 'dimension'; min: number; max: number }
  | { type: 'color' }
  | { type: 'enum'; enum: string }
  | { type: 'weight'; min: number; max: number; step: number }
)

type Members = Record<string, string[]>

/** A nested object's members, or a tagged object's tag and each variant's members. */
type Payload = string[] | { tag: string; variants: Members }

export interface Schema {
  constants: Constant[]
  limits: string[]
  enums: Record<string, EnumSpec>
  style: StyleField[]
  elements: Members
  operations: Members
  groups: Members
  commands: Members
  events: Members
  modifiers: string[]
  /** Rust error texts; `{NAME}` is replaced by that constant's value. */
  messages: Record<string, string>
  /** Menu shortcut keys besides letters, digits and function keys. */
  app_menu_keys: { named: string[]; punctuation: string[] }
  payloads: Record<string, Payload>
}

const HEADER =
  '@generated by scripts/protocol/schema.ts from ' +
  SCHEMA_PATH +
  '. Do not edit: change the schema and run `bun run generate:schema`.'

const snake = /^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$/
const pascal = (name: string) =>
  name
    .split('_')
    .map((part) => part[0]!.toUpperCase() + part.slice(1))
    .join('')

function fail(message: string): never {
  throw new Error('wire schema: ' + message)
}

function unique(names: readonly string[], where: string): void {
  const seen = new Set<string>()
  for (const name of names) {
    if (seen.has(name)) fail(`${where} repeats ${name}`)
    seen.add(name)
  }
}

function valueName(value: EnumValue): string {
  return typeof value === 'string' ? value : value.name
}

function valueDoc(value: EnumValue): string | undefined {
  return typeof value === 'string' ? undefined : value.doc
}

/** Expands `@group` references; every list is checked for unique snake_case names. */
function expand(members: Members, groups: Members, where: string): Members {
  const result: Members = {}
  for (const [tag, list] of Object.entries(members)) {
    if (!snake.test(tag)) fail(`${where} tag ${tag} is not snake_case`)
    const names = list.flatMap((name) => {
      if (!name.startsWith('@')) return [name]
      return groups[name.slice(1)] ?? fail(`${where} ${tag} names unknown group ${name}`)
    })
    for (const name of names)
      if (!snake.test(name)) fail(`${where} member ${name} is not snake_case`)
    unique(names, `${where} ${tag}`)
    result[tag] = names
  }
  return result
}

/** Checks references and names, and expands groups, so both renderers read one shape. */
export function resolveSchema(schema: Schema): Schema {
  unique(
    schema.constants.map((constant) => constant.name),
    'constants'
  )
  const constants = new Map(schema.constants.map((constant) => [constant.name, constant]))
  for (const constant of schema.constants) {
    if (!/^[A-Z][A-Z0-9_]*$/.test(constant.name))
      fail(`constant ${constant.name} is not upper case`)
    const type = constant.rust ?? 'usize'
    if (type !== 'f64' && !Number.isSafeInteger(constant.value))
      fail(`constant ${constant.name} must be an integer`)
  }
  unique(schema.limits, 'limits')
  for (const name of schema.limits) {
    const constant = constants.get(name) ?? fail(`limit ${name} is not a constant`)
    if ((constant.rust ?? 'usize') !== 'usize') fail(`limit ${name} must be a usize constant`)
  }
  for (const [name, spec] of Object.entries(schema.enums)) {
    if (!/^[A-Z][A-Za-z0-9]*$/.test(name)) fail(`enum ${name} is not PascalCase`)
    const values = spec.values.map(valueName)
    if (!values.length) fail(`enum ${name} has no values`)
    for (const value of values)
      if (!snake.test(value)) fail(`enum ${name} value ${value} is not snake_case`)
    unique(values, `enum ${name}`)
    if (spec.default !== undefined && !values.includes(spec.default))
      fail(`enum ${name} default ${spec.default} is not a value`)
    const required = spec.values.map(
      (value) => typeof value !== 'string' && value.required === true
    )
    if (required.indexOf(false) >= 0 && required.lastIndexOf(true) > required.indexOf(false))
      fail(`enum ${name} must list its required values first`)
  }
  unique(
    schema.style.map((field) => field.name),
    'style'
  )
  for (const field of schema.style) {
    if (!snake.test(field.name)) fail(`style field ${field.name} is not snake_case`)
    if (field.type === 'enum' && !schema.enums[field.enum])
      fail(`style field ${field.name} names unknown enum ${field.enum}`)
    if ('min' in field && !(field.min <= field.max)) fail(`style field ${field.name} has min > max`)
  }
  const depth = constants.get('MAX_DEPTH')?.value
  if (constants.get('MAX_EVENT_PATH_NODES')?.value !== (depth ?? 0) + 1)
    fail('MAX_EVENT_PATH_NODES must be MAX_DEPTH + 1')
  for (const [name, text] of Object.entries(schema.messages)) {
    if (!/^[A-Z][A-Z0-9_]*$/.test(name)) fail(`message ${name} is not upper case`)
    for (const [, reference] of text.matchAll(/\{([^}]*)\}/g))
      if (!constants.has(reference!)) fail(`message ${name} names unknown constant ${reference}`)
  }
  unique([...schema.app_menu_keys.named, ...schema.app_menu_keys.punctuation], 'app_menu_keys')
  for (const [name, payload] of Object.entries(schema.payloads)) {
    if (!snake.test(name)) fail(`payload ${name} is not snake_case`)
    if (Array.isArray(payload)) expand({ [name]: payload }, {}, 'payload')
    else {
      if (!snake.test(payload.tag)) fail(`payload ${name} tag ${payload.tag} is not snake_case`)
      expand(payload.variants, {}, `payload ${name}`)
    }
  }
  unique(schema.modifiers, 'modifiers')
  for (const [name, members] of Object.entries(schema.groups))
    for (const member of members)
      if (!snake.test(member)) fail(`group ${name} member ${member} is not snake_case`)
  const elements = expand(schema.elements, {}, 'element')
  const operations = expand(schema.operations, {}, 'operation')
  if (Object.keys(elements).length > 32 || Object.keys(operations).length > 32)
    fail('element and operation tags must fit a 32-bit member mask')
  for (const [where, table] of [
    ['element', elements],
    ['operation', operations],
  ] as const)
    if (new Set(Object.values(table).flat()).size > 31)
      fail(`${where} members must fit a 32-bit member mask`)
  return {
    ...schema,
    elements,
    operations,
    commands: expand(schema.commands, schema.groups, 'command'),
    events: expand(schema.events, schema.groups, 'event'),
  }
}

export function readSchema(root: string): Schema {
  return resolveSchema(JSON.parse(readFileSync(join(root, SCHEMA_PATH), 'utf8')) as Schema)
}

/** Digit groups of three from four digits on, as the hand-written sources spell them. */
function digits(value: number): string {
  const text = String(Math.abs(value))
  const grouped = text.length < 4 ? text : text.replace(/\B(?=(\d{3})+$)/g, '_')
  return (value < 0 ? '-' : '') + grouped
}

function rustNumber(value: number, type: RustType): string {
  if (type !== 'f64') return digits(value)
  return Number.isInteger(value) ? digits(value) + '.0' : String(value)
}

function quote(value: string): string {
  return JSON.stringify(value)
}

function comment(prefix: string, text: string | undefined, width = 100): string[] {
  if (!text) return []
  const lines: string[] = []
  let line = ''
  for (const word of text.split(/\s+/)) {
    if (line && prefix.length + line.length + 1 + word.length > width) {
      lines.push(prefix + line)
      line = word
    } else line = line ? line + ' ' + word : word
  }
  lines.push(prefix + line)
  return lines
}

function jsDoc(indent: string, text: string | undefined): string[] {
  if (!text) return []
  const single = `${indent}/** ${text} */`
  if (single.length <= 100) return [single]
  return [`${indent}/**`, ...comment(indent + ' * ', text), `${indent} */`]
}

/** The field's own doc, its capability and its accepted range. */
function styleDoc(field: StyleField): string {
  const range =
    field.type === 'number' || field.type === 'dimension'
      ? `${field.min} to ${field.max}${field.type === 'dimension' ? ', or `fill`' : ''}.`
      : field.type === 'weight'
        ? `${field.min} to ${field.max} in steps of ${field.step}.`
        : field.type === 'color'
          ? 'Unsigned 24-bit RGB.'
          : ''
  const text = [field.doc, range].filter(Boolean).join(' ')
  return field.decoration
    ? '`style_decoration_v1`: ' + text[0]!.toLowerCase() + text.slice(1)
    : text
}

function tagTable(tag: string, table: Members): string[] {
  const lines = [`Object.freeze({`]
  for (const [name, members] of Object.entries(table)) {
    const list = [tag, ...members].map((member) => `'${member}'`).join(', ')
    const entry = `  ${name}: new Set([${list}] as const),`
    if (entry.length <= 100) lines.push(entry)
    else {
      lines.push(`  ${name}: new Set([`)
      for (const member of [tag, ...members]) lines.push(`    '${member}',`)
      lines.push(`  ] as const),`)
    }
  }
  lines.push('})')
  return lines
}

function tsList(values: readonly string[], indent: string): string[] {
  const inline = values.map((value) => `'${value}'`).join(', ')
  if (indent.length + inline.length + 30 <= 100) return [inline]
  return values.map((value) => `${indent}'${value}',`)
}

export function renderTypeScript(schema: Schema): string {
  const out: string[] = [`// ${HEADER}`, '']
  for (const constant of schema.constants) {
    out.push(...jsDoc('', constant.doc))
    out.push(
      `${constant.export === false ? '' : 'export '}const ${constant.name} = ${digits(constant.value)}`
    )
  }

  out.push('', 'export interface Limits {')
  for (const name of schema.limits) out.push(`  ${name.toLowerCase()}: number`)
  out.push('}', '', 'export const DEFAULT_LIMITS: Readonly<Limits> = Object.freeze({')
  for (const name of schema.limits) out.push(`  ${name.toLowerCase()}: ${name},`)
  out.push('})')

  for (const [name, spec] of Object.entries(schema.enums)) {
    out.push('')
    const values = spec.values.map(valueName)
    if (spec.ts) {
      const required = spec.values.filter((value) => typeof value !== 'string' && value.required)
      const spread = required.length ? ['  ...REQUIRED_' + spec.ts + ','] : []
      if (required.length) {
        out.push(`export const REQUIRED_${spec.ts} = Object.freeze([`)
        for (const value of required) out.push(`  '${valueName(value)}',`)
        out.push('] as const)')
      }
      out.push(...jsDoc('', spec.doc))
      out.push(`export const ${spec.ts} = Object.freeze([`, ...spread)
      for (const value of spec.values.slice(required.length)) {
        out.push(...jsDoc('  ', valueDoc(value)))
        out.push(`  '${valueName(value)}',`)
      }
      out.push('] as const)')
      out.push(`export type ${name} = (typeof ${spec.ts})[number]`)
    } else {
      out.push(...jsDoc('', spec.doc))
      out.push(`export type ${name} = ${values.map((value) => `'${value}'`).join(' | ')}`)
    }
  }

  out.push('', 'export interface Style {')
  for (const field of schema.style) {
    out.push(...jsDoc('  ', styleDoc(field)))
    const type =
      field.type === 'enum'
        ? field.enum
        : field.type === 'dimension'
          ? `number | 'fill'`
          : field.type === 'weight'
            ? Array.from(
                { length: (field.max - field.min) / field.step + 1 },
                (_, index) => field.min + index * field.step
              ).join(' | ')
            : 'number'
    out.push(`  ${field.name}?: ${type}`)
  }
  out.push('}', '')
  out.push('/** Style fields that require `style_decoration_v1`. */')
  out.push('export const DECORATION_FIELDS = Object.freeze([')
  for (const field of schema.style.filter((field) => field.decoration))
    out.push(`  '${field.name}',`)
  out.push('] as const)', '')
  out.push(
    '/** How one style field is checked: a finite range, `fill` or a range, RGB, a value list or a stepped range. */',
    'export type StyleField =',
    "  | { readonly type: 'number' | 'dimension'; readonly min: number; readonly max: number }",
    "  | { readonly type: 'color' }",
    "  | { readonly type: 'enum'; readonly values: readonly string[] }",
    "  | { readonly type: 'weight'; readonly min: number; readonly max: number; readonly step: number }",
    '',
    'export const STYLE_FIELDS: ReadonlyMap<string, StyleField> = new Map<string, StyleField>(['
  )
  for (const field of schema.style) {
    let spec: string
    if (field.type === 'enum') {
      const values = schema.enums[field.enum]!.values.map(valueName)
      const inline = `  ['${field.name}', { type: 'enum', values: [${tsList(values, '')}] }],`
      if (inline.length <= 100) {
        out.push(inline)
        continue
      }
      out.push(`  [`, `    '${field.name}',`, `    {`, `      type: 'enum',`, `      values: [`)
      out.push(...values.map((value) => `        '${value}',`))
      out.push(`      ],`, `    },`, `  ],`)
      continue
    }
    if (field.type === 'color') spec = `{ type: 'color' }`
    else if (field.type === 'weight')
      spec = `{ type: 'weight', min: ${field.min}, max: ${field.max}, step: ${field.step} }`
    else spec = `{ type: '${field.type}', min: ${digits(field.min)}, max: ${digits(field.max)} }`
    out.push(`  ['${field.name}', ${spec}],`)
  }
  out.push('])', '')

  const tables: [string, string, string, Members][] = [
    ['Members of each element kind, `kind` included.', 'ELEMENT_KEYS', 'kind', schema.elements],
    [
      'Members of each tree operation, `type` included.',
      'OPERATION_KEYS',
      'type',
      schema.operations,
    ],
    ['Members of each command, `type` included.', 'COMMAND_KEYS', 'type', schema.commands],
    ['Members of each event, `type` included.', 'EVENT_KEYS', 'type', schema.events],
  ]
  for (const [doc, name, tag, table] of tables)
    out.push(`/** ${doc} */`, `export const ${name} = ${tagTable(tag, table).join('\n')}`, '')
  out.push("/** Members of a key or pointer event's `modifiers`. */")
  out.push(
    `export const MODIFIER_KEYS = new Set([${schema.modifiers.map((name) => `'${name}'`).join(', ')}] as const)`,
    ''
  )
  out.push('/** Named menu shortcut keys besides letters, digits and function keys. */')
  out.push(`export const APP_MENU_NAMED_KEYS = Object.freeze([`)
  out.push(...schema.app_menu_keys.named.map((key) => `  ${quote(key)},`), '] as const)')
  out.push('/** Punctuation menu shortcut keys. */')
  out.push(`export const APP_MENU_PUNCTUATION_KEYS = Object.freeze([`)
  out.push(...schema.app_menu_keys.punctuation.map((key) => `  ${quote(key)},`), '] as const)', '')
  out.push(
    '/** Members of each nested payload object; each variant of a tagged one includes the tag. */'
  )
  out.push('export const PAYLOAD_KEYS = Object.freeze({')
  for (const [name, payload] of Object.entries(schema.payloads)) {
    if (Array.isArray(payload)) {
      out.push(
        `  ${name}: new Set([${payload.map((member) => `'${member}'`).join(', ')}] as const),`
      )
      continue
    }
    const table = tagTable(payload.tag, payload.variants)
    out.push(`  ${name}: ${table[0]}`, ...table.slice(1, -1).map((line) => '  ' + line), '  }),')
  }
  out.push('})')
  return out.join('\n') + '\n'
}

function rustDoc(indent: string, text: string | undefined): string[] {
  return comment(indent + '/// ', text)
}

/** A tagged object's kind enum, member enum and masks, for the hand-written decoders. */
function rustTagTable(prefix: string, tag: string, table: Members): string[] {
  const kinds = Object.keys(table)
  const members = [tag, ...new Set(Object.values(table).flat())]
  const out: string[] = []
  const lower = prefix.toLowerCase()
  out.push(`/// The \`${tag}\` of ${/^[aeiou]/.test(lower) ? 'an' : 'a'} ${lower}.`)
  out.push('#[derive(Clone, Copy)]', `pub(crate) enum ${prefix}Kind {`)
  out.push(...kinds.map((kind) => `    ${pascal(kind)},`), '}', '')
  out.push(`pub(crate) const ${prefix.toUpperCase()}_KINDS: &[&str] = &[`)
  out.push(...kinds.map((kind) => `    ${quote(kind)},`), '];', '')
  out.push(`impl ${prefix}Kind {`)
  out.push('    pub(crate) fn from_name(name: &str) -> Option<Self> {', '        Some(match name {')
  out.push(...kinds.map((kind) => `            ${quote(kind)} => Self::${pascal(kind)},`))
  out.push('            _ => return None,', '        })', '    }', '')
  out.push(`    /// One bit per [\`${prefix}Member\`] this kind accepts, \`${tag}\` included.`)
  out.push('    pub(crate) const fn members(self) -> u32 {', '        match self {')
  for (const kind of kinds) {
    const bits = [tag, ...table[kind]!].map((member) => 1 << members.indexOf(member))
    const mask = bits.reduce((left, right) => left | right, 0)
    out.push(`            Self::${pascal(kind)} => 0b${mask.toString(2)},`)
  }
  out.push('        }', '    }', '')
  out.push('    /// The member names this kind accepts, for error messages.')
  out.push("    pub(crate) const fn member_names(self) -> &'static [&'static str] {")
  out.push('        match self {')
  for (const kind of kinds) {
    const names = [tag, ...table[kind]!].map(quote).join(', ')
    const line = `            Self::${pascal(kind)} => &[${names}],`
    if (line.length <= 100) out.push(line)
    else {
      out.push(`            Self::${pascal(kind)} => &[`)
      out.push(...[tag, ...table[kind]!].map((name) => `                ${quote(name)},`))
      out.push('            ],')
    }
  }
  out.push('        }', '    }', '}', '')
  out.push(`/// Every member any ${lower} accepts; the discriminant is its mask bit.`)
  out.push('#[derive(Clone, Copy)]', `pub(crate) enum ${prefix}Member {`)
  out.push(...members.map((member) => `    ${pascal(member)},`), '}', '')
  out.push(`pub(crate) const ${prefix.toUpperCase()}_MEMBERS: &[&str] = &[`)
  out.push(...members.map((member) => `    ${quote(member)},`), '];', '')
  out.push(`impl ${prefix}Member {`)
  out.push('    pub(crate) fn from_name(name: &str) -> Option<Self> {', '        Some(match name {')
  out.push(...members.map((member) => `            ${quote(member)} => Self::${pascal(member)},`))
  out.push('            _ => return None,', '        })', '    }', '')
  out.push('    pub(crate) const fn bit(self) -> u32 {', '        1 << (self as u32)', '    }', '}')
  return out
}

function rustMembers(name: string, table: Members): string[] {
  const out = ['#[cfg(test)]', `pub(crate) const ${name}: &[(&str, &[&str])] = &[`]
  for (const [tag, members] of Object.entries(table)) {
    const line = `    (${quote(tag)}, &[${members.map(quote).join(', ')}]),`
    if (line.length <= 100) out.push(line)
    else {
      out.push('    (', `        ${quote(tag)},`, '        &[')
      out.push(...members.map((member) => `            ${quote(member)},`))
      out.push('        ],', '    ),')
    }
  }
  out.push('];')
  return out
}

export function renderRust(schema: Schema): string {
  const out: string[] = [`// ${HEADER}`, '']
  out.push('use super::{bounded, non_null, non_null_color, Dimension};')
  out.push('use serde::{Deserialize, Serialize};', '')
  for (const constant of schema.constants) {
    const type = constant.rust ?? 'usize'
    out.push(...rustDoc('', constant.doc))
    out.push(`pub const ${constant.name}: ${type} = ${rustNumber(constant.value, type)};`)
  }

  for (const [name, spec] of Object.entries(schema.enums)) {
    out.push('')
    out.push(...rustDoc('', spec.doc))
    const derive = spec.default === undefined ? '' : 'Default, '
    out.push(`#[derive(Debug, ${derive}Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]`)
    out.push('#[serde(rename_all = "snake_case")]', `pub enum ${name} {`)
    for (const value of spec.values) {
      out.push(...rustDoc('    ', valueDoc(value)))
      if (valueName(value) === spec.default) out.push('    #[default]')
      out.push(`    ${pascal(valueName(value))},`)
    }
    out.push('}')
  }

  out.push('', '#[derive(Debug, Default, Clone, PartialEq, Serialize, Deserialize)]')
  out.push('#[serde(deny_unknown_fields)]', 'pub struct Style {')
  for (const field of schema.style) {
    const type =
      field.type === 'enum'
        ? field.enum
        : field.type === 'dimension'
          ? 'Dimension'
          : field.type === 'color'
            ? 'u32'
            : 'f64'
    const decode = field.type === 'color' ? 'non_null_color' : 'non_null'
    out.push(...rustDoc('    ', styleDoc(field)))
    out.push('    #[serde(', '        default,', '        skip_serializing_if = "Option::is_none",')
    out.push(`        deserialize_with = "${decode}"`, '    )]')
    out.push(`    pub ${field.name}: Option<${type}>,`)
  }
  out.push('}', '', 'impl Style {')
  out.push("    /// Each field's own bounds; `validate` adds the rules between fields.")
  out.push("    pub(super) fn validate_fields(&self) -> Result<(), &'static str> {")
  for (const field of schema.style) {
    if (field.type === 'enum') continue
    if (field.type === 'color') {
      out.push(`        if self.${field.name}.is_some_and(|value| value > 0xff_ffff) {`)
      out.push(`            return Err("${field.name} must be an unsigned 24-bit RGB value");`)
      out.push('        }')
      continue
    }
    const range = `${rustNumber(field.min, 'f64')}, ${rustNumber(field.max, 'f64')}`
    const message =
      field.type === 'weight'
        ? `${field.name} must be ${field.min}-${field.max} in steps of ${field.step}`
        : `${field.name} must be between ${field.min} and ${field.max}`
    const pattern = field.type === 'dimension' ? 'Some(Dimension::Pixels(value))' : 'Some(value)'
    out.push(`        if let ${pattern} = self.${field.name} {`)
    out.push(`            bounded(value, ${range}, ${quote(message)})?;`)
    if (field.type === 'weight') {
      out.push(`            if value % ${rustNumber(field.step, 'f64')} != 0.0 {`)
      out.push(`                return Err(${quote(message)});`, '            }')
    }
    out.push('        }')
  }
  out.push('        Ok(())', '    }', '')
  out.push('    /// Whether any field needs `style_decoration_v1`.', '    #[cfg(test)]')
  out.push('    pub(crate) fn uses_decoration(&self) -> bool {')
  const decoration = schema.style.filter((field) => field.decoration)
  decoration.forEach((field, index) =>
    out.push(`        ${index ? '|| ' : ''}self.${field.name}.is_some()`)
  )
  out.push('    }', '}', '')

  out.push('#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]')
  out.push('#[serde(deny_unknown_fields)]', 'pub struct Limits {')
  for (const name of schema.limits) out.push(`    pub ${name.toLowerCase()}: usize,`)
  out.push('}', '', 'impl Default for Limits {', '    fn default() -> Self {', '        Self {')
  for (const name of schema.limits) out.push(`            ${name.toLowerCase()}: ${name},`)
  out.push('        }', '    }', '}', '', 'impl Limits {')
  out.push('    /// Advertised limits may only narrow the protocol defaults, never widen or')
  out.push('    /// disable a resource (the TypeScript reader bounds each to `1..=default`).')
  out.push("    pub fn validate(&self) -> Result<(), &'static str> {")
  out.push('        let defaults = Self::default();', '        let pairs = [')
  for (const name of schema.limits) {
    const field = name.toLowerCase()
    out.push(`            (self.${field}, defaults.${field}),`)
  }
  out.push('        ];')
  out.push('        if pairs', '            .into_iter()')
  out.push('            .any(|(value, default)| value == 0 || value > default)', '        {')
  out.push('            return Err("ready limits must be between 1 and the protocol default");')
  out.push('        }', '        Ok(())', '    }', '}', '')

  out.push(...rustTagTable('Element', 'kind', schema.elements), '')
  out.push(...rustTagTable('Operation', 'type', schema.operations), '')
  out.push(...rustMembers('COMMAND_MEMBERS', schema.commands), '')
  out.push(...rustMembers('EVENT_MEMBERS', schema.events), '')
  out.push('#[cfg(test)]')
  out.push(
    `pub(crate) const MODIFIER_MEMBERS: &[&str] = &[${schema.modifiers.map(quote).join(', ')}];`,
    ''
  )
  const { named, punctuation } = schema.app_menu_keys
  out.push('/// Named menu shortcut keys besides `a`-`z`, `0`-`9` and `f1`-`f12`.')
  out.push(`pub const APP_MENU_NAMED_KEYS: [&str; ${named.length}] = [`)
  out.push(...named.map((key) => `    ${quote(key)},`), '];')
  out.push('/// Punctuation menu shortcut keys.')
  out.push(`pub const APP_MENU_PUNCTUATION_KEYS: [&str; ${punctuation.length}] = [`)
  out.push(...punctuation.map((key) => `    ${quote(key)},`), '];', '')
  const plain = Object.entries(schema.payloads).filter((entry): entry is [string, string[]] =>
    Array.isArray(entry[1])
  )
  out.push(...rustMembers('PAYLOAD_MEMBERS', Object.fromEntries(plain)), '')
  out.push('/// A tagged payload: its name, its tag and the members of each variant.')
  out.push('#[cfg(test)]', 'pub(crate) type TaggedMembers =')
  out.push("    (&'static str, &'static str, &'static [(&'static str, &'static [&'static str])]);")
  out.push('', '#[cfg(test)]', 'pub(crate) const TAGGED_PAYLOAD_MEMBERS: &[TaggedMembers] = &[')
  for (const [name, payload] of Object.entries(schema.payloads)) {
    if (Array.isArray(payload)) continue
    out.push('    (', `        ${quote(name)},`, `        ${quote(payload.tag)},`, '        &[')
    for (const [tag, members] of Object.entries(payload.variants))
      out.push(`            (${quote(tag)}, &[${members.map(quote).join(', ')}]),`)
    out.push('        ],', '    ),')
  }
  out.push('];')
  for (const [name, text] of Object.entries(schema.messages)) {
    const value = text.replace(/\{([^}]*)\}/g, (_, reference: string) =>
      String(schema.constants.find((constant) => constant.name === reference)!.value)
    )
    out.push('', `pub(crate) const ${name}: &str = ${quote(value)};`)
  }
  return out.join('\n') + '\n'
}

/**
 * Formats TypeScript with the pinned Bun's formatter and the repository's
 * settings, so the output is what `bun fmt` keeps. The Rust module is written
 * formatted and declared `#[rustfmt::skip]`, so no Rust toolchain is needed.
 */
function format(root: string, path: string, text: string): string {
  const result = Bun.spawnSync([process.execPath, 'fmt', '--no-script', '--stdin-filepath', path], {
    cwd: root,
    stdin: new TextEncoder().encode(text),
  })
  if (result.exitCode !== 0) fail(`bun fmt failed for ${path}: ${result.stderr.toString()}`)
  return result.stdout.toString()
}

export function render(root: string): Map<string, string> {
  const schema = readSchema(root)
  return new Map([
    [TYPESCRIPT_PATH, format(root, TYPESCRIPT_PATH, renderTypeScript(schema))],
    [RUST_PATH, renderRust(schema)],
  ])
}

/** Writes the generated files, or with `--check` reports each stale one and returns 1. */
export function main(args: readonly string[], root = resolve(import.meta.dir, '../..')): number {
  const check = args.includes('--check')
  const stale: string[] = []
  for (const [path, text] of render(root)) {
    const file = join(root, path)
    let current: string | undefined
    try {
      current = readFileSync(file, 'utf8')
    } catch {
      current = undefined
    }
    if (current === text) continue
    if (check) stale.push(path)
    else writeFileSync(file, text)
  }
  if (stale.length) {
    console.error(
      `Stale generated wire schema: ${stale.join(', ')}. Run bun run generate:schema and commit the result.`
    )
    return 1
  }
  return 0
}

if (import.meta.main) process.exitCode = main(process.argv.slice(2))
